   pts=' '.join(f'{170+(vv[i][0]-xmin)*scale:.2f},{615-(vv[i][1]-ymin)*scale:.2f}' for i in f);faces.append((sum(vv[i][2] for i in f)/3,f'<polygon points="{pts}" fill="{colors(n)}" fill-opacity="{.22 if n.startswith("Drill") else .78 if n.startswith("Bit") else 1}" stroke="#30434c" stroke-width=".24"/>'))
