 text += [f for _,f in sorted(faces)];text += [f'<text x="28" y="670" font-size="16">{html.escape(note)}</text>', '<text x="28" y="699" font-size="14">Diagonal datum + TOP stop · raised arrow UP · clamp jaws are reserves, not complete selected clamps.</text>','<text x="28" y="732" font-size="12">CERN-OHL-S-2.0 · Source Location: github.com/advpeterrobinson-hash/vpin-cabinet</text></g></svg>'];(O/name).write_text(''.join(text))
